#!/usr/bin/env node
/**
 * ACP bridge for the Agent Workspace template.
 *
 * Browsers cannot spawn processes or touch your files, so this small Node
 * server sits between the web UI and any Agent Client Protocol agent:
 *
 *   browser ── WebSocket (JSON-RPC) ──► acp-bridge ── stdio (ndjson) ──► agent
 *
 * - The browser sends `_bridge/spawn` with the agent's command, then speaks
 *   plain ACP (initialize, session/new, session/prompt, …); the bridge pipes it
 *   to the agent's stdin and pipes the agent's stdout back.
 * - Client-side methods the agent calls (fs/read_text_file,
 *   fs/write_text_file, terminal/*) are answered here, inside --root only.
 *   Terminal output and file writes are mirrored to the browser as `_bridge/*`
 *   notifications so the UI can show live output and offer Undo.
 * - `_bridge/list_files`, `_bridge/read_file`, `_bridge/write_file` and
 *   `_bridge/exec` power the explorer, the edited-files Undo and the terminal.
 *
 * Usage:
 *   node server/acp-bridge.mjs --root . [--port 8787] [--host 127.0.0.1] [--token <secret>]
 *
 * Every connection must present the token (printed at start, or
 * ACP_BRIDGE_TOKEN). Anyone holding it can run commands as you, so keep the
 * default 127.0.0.1 binding unless you know what you are doing.
 *
 * Requires Node 18+ and the `ws` package.
 */
import { spawn, execFile } from "node:child_process"
import { randomBytes, timingSafeEqual } from "node:crypto"
import { existsSync, statSync } from "node:fs"
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises"
import { createServer } from "node:http"
import path from "node:path"
import { WebSocketServer } from "ws"

/* --------------------------------- options -------------------------------- */

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`)
  return i > 0 && process.argv[i + 1] ? process.argv[i + 1] : fallback
}

const ROOT = path.resolve(arg("root", process.env.ACP_BRIDGE_ROOT ?? process.cwd()))
const PORT = Number(arg("port", process.env.ACP_BRIDGE_PORT ?? 8787))
const HOST = arg("host", process.env.ACP_BRIDGE_HOST ?? "127.0.0.1")
const TOKEN = arg("token", process.env.ACP_BRIDGE_TOKEN ?? randomBytes(12).toString("hex"))
const VERBOSE = process.argv.includes("--verbose") || process.env.ACP_BRIDGE_VERBOSE === "1"
const MAX_FILE = 2 * 1024 * 1024
const MAX_FILES = 5000

if (!existsSync(ROOT) || !statSync(ROOT).isDirectory()) {
  console.error(`acp-bridge: --root ${ROOT} is not a directory`)
  process.exit(1)
}

const log = (...a) => VERBOSE && console.error("[acp-bridge]", ...a)

/* --------------------------------- helpers -------------------------------- */

/** Resolve a path from the agent or the UI and refuse anything outside ROOT. */
function inside(p) {
  if (typeof p !== "string" || !p) throw rpcError(-32602, "path is required")
  const abs = path.resolve(ROOT, p)
  const rel = path.relative(ROOT, abs)
  if (rel.startsWith("..") || path.isAbsolute(rel)) throw rpcError(-32602, `Path is outside the workspace root: ${p}`)
  return abs
}

function rpcError(code, message, data) {
  const e = new Error(message)
  e.code = code
  e.data = data
  return e
}

/** Keep at most `limit` bytes from the end of `text`, cutting at a character boundary. */
function tail(text, limit) {
  if (!limit || Buffer.byteLength(text) <= limit) return { text, truncated: false }
  const buf = Buffer.from(text)
  let start = buf.length - limit
  while (start < buf.length && (buf[start] & 0xc0) === 0x80) start++
  return { text: buf.subarray(start).toString("utf8"), truncated: true }
}

async function listFiles() {
  const viaGit = await new Promise((resolve) => {
    execFile("git", ["-C", ROOT, "ls-files", "--cached", "--others", "--exclude-standard"], { maxBuffer: 32 * 1024 * 1024 }, (err, stdout) =>
      resolve(err ? null : stdout.split("\n").filter(Boolean))
    )
  })
  if (viaGit) return viaGit.slice(0, MAX_FILES)
  const out = []
  const skip = new Set(["node_modules", ".git", ".next", "dist", "build", ".turbo", ".cache"])
  async function walk(dir) {
    if (out.length >= MAX_FILES) return
    for (const entry of await readdir(dir, { withFileTypes: true }).catch(() => [])) {
      if (out.length >= MAX_FILES) return
      if (skip.has(entry.name)) continue
      const abs = path.join(dir, entry.name)
      if (entry.isDirectory()) await walk(abs)
      else out.push(path.relative(ROOT, abs).split(path.sep).join("/"))
    }
  }
  await walk(ROOT)
  return out
}

/* ------------------------------- connections ------------------------------ */

function handleConnection(ws) {
  /** @type {import("node:child_process").ChildProcess | null} */
  let agent = null
  let buffer = ""
  const terminals = new Map()
  let nextTerminal = 1

  const toBrowser = (msg) => ws.readyState === ws.OPEN && ws.send(JSON.stringify(msg))
  const notify = (method, params) => toBrowser({ jsonrpc: "2.0", method, params })
  const toAgent = (msg) => {
    if (!agent?.stdin?.writable) return false
    agent.stdin.write(`${JSON.stringify(msg)}\n`)
    return true
  }

  /* ----------------------------- terminals ------------------------------ */

  function startTerminal({ command, args = [], env = [], cwd, outputByteLimit, sessionId, terminalId, title }) {
    const id = terminalId ?? `term_${nextTerminal++}`
    const workdir = cwd ? inside(cwd) : ROOT
    const envObj = { ...process.env, FORCE_COLOR: "1" }
    for (const v of env) envObj[v.name] = v.value
    // A bare command line (no args) goes through the shell, so pipes and && work.
    const child = args.length ? spawn(command, args, { cwd: workdir, env: envObj }) : spawn(command, { cwd: workdir, env: envObj, shell: true })
    const term = { id, child, output: "", truncated: false, exitStatus: null, limit: outputByteLimit ?? 1024 * 1024, waiters: [] }
    terminals.set(id, term)
    const onData = (chunk) => {
      const data = chunk.toString("utf8")
      const next = tail(term.output + data, term.limit)
      term.output = next.text
      term.truncated ||= next.truncated
      notify("_bridge/terminal_output", { terminalId: id, data, sessionId, title: title ?? [command, ...args].join(" ").slice(0, 40) })
    }
    child.stdout.on("data", onData)
    child.stderr.on("data", onData)
    const finish = (exitCode, signal) => {
      if (term.exitStatus) return
      term.exitStatus = { exitCode, signal }
      notify("_bridge/terminal_exit", { terminalId: id, exitStatus: term.exitStatus })
      for (const w of term.waiters) w(term.exitStatus)
      term.waiters = []
    }
    child.on("exit", (code, signal) => finish(code, signal))
    child.on("error", (err) => {
      onData(Buffer.from(`${err.message}\n`))
      finish(127, null)
    })
    return term
  }

  function terminal(id) {
    const t = terminals.get(id)
    if (!t) throw rpcError(-32602, `Unknown terminal ${id}`)
    return t
  }

  /* ------------------- client methods the agent calls ------------------- */

  const clientMethods = {
    async "fs/read_text_file"({ path: p, line, limit }) {
      const text = await readFile(inside(p), "utf8")
      if (line == null && limit == null) return { content: text }
      const lines = text.split("\n")
      const start = Math.max(0, (line ?? 1) - 1)
      return { content: lines.slice(start, limit == null ? undefined : start + limit).join("\n") }
    },
    async "fs/write_text_file"({ path: p, content, sessionId }) {
      const abs = inside(p)
      const oldText = await readFile(abs, "utf8").catch(() => null)
      await mkdir(path.dirname(abs), { recursive: true })
      await writeFile(abs, content, "utf8")
      notify("_bridge/fs_write", { sessionId, path: abs, oldText, newText: content })
      return {}
    },
    async "terminal/create"(params) {
      return { terminalId: startTerminal(params).id }
    },
    async "terminal/output"({ terminalId }) {
      const t = terminal(terminalId)
      return { output: t.output, truncated: t.truncated, ...(t.exitStatus ? { exitStatus: t.exitStatus } : {}) }
    },
    async "terminal/wait_for_exit"({ terminalId }) {
      const t = terminal(terminalId)
      return t.exitStatus ?? new Promise((resolve) => t.waiters.push(resolve))
    },
    async "terminal/kill"({ terminalId }) {
      const t = terminal(terminalId)
      if (!t.exitStatus) t.child.kill("SIGTERM")
      return {}
    },
    async "terminal/release"({ terminalId }) {
      const t = terminals.get(terminalId)
      if (t && !t.exitStatus) t.child.kill("SIGTERM")
      terminals.delete(terminalId)
      return {}
    },
  }

  /* -------------------- bridge methods the UI calls --------------------- */

  const bridgeMethods = {
    async "_bridge/spawn"({ command, args = [], env = {} }) {
      if (!command) throw rpcError(-32602, "command is required")
      if (agent) agent.kill()
      log("spawn", command, args.join(" "))
      const child = spawn(command, args, {
        cwd: ROOT,
        env: { ...process.env, ...env },
        stdio: ["pipe", "pipe", "pipe"],
        shell: process.platform === "win32",
      })
      agent = child
      buffer = ""
      child.stdout.on("data", (chunk) => {
        buffer += chunk.toString("utf8")
        let nl
        while ((nl = buffer.indexOf("\n")) >= 0) {
          const line = buffer.slice(0, nl).trim()
          buffer = buffer.slice(nl + 1)
          if (line) void fromAgent(line)
        }
      })
      child.stderr.on("data", (chunk) => notify("_bridge/agent_stderr", { data: chunk.toString("utf8") }))
      child.on("exit", (code, signal) => {
        log("agent exited", code, signal)
        if (agent === child) agent = null
        notify("_bridge/agent_exit", { code, signal })
      })
      await new Promise((resolve, reject) => {
        child.once("spawn", resolve)
        child.once("error", (err) => reject(rpcError(-32000, `Could not start ${command}: ${err.message}`)))
      })
      return { root: ROOT, pid: child.pid }
    },
    async "_bridge/list_files"() {
      return { files: await listFiles(), root: ROOT }
    },
    async "_bridge/read_file"({ path: p }) {
      const abs = inside(p)
      if (statSync(abs).size > MAX_FILE) throw rpcError(-32000, "File is too large to preview")
      return { content: await readFile(abs, "utf8") }
    },
    async "_bridge/write_file"({ path: p, content }) {
      const abs = inside(p)
      if (content === null || content === undefined) await rm(abs, { force: true })
      else {
        await mkdir(path.dirname(abs), { recursive: true })
        await writeFile(abs, content, "utf8")
      }
      return null
    },
    async "_bridge/exec"({ command, terminalId }) {
      const t = startTerminal({ command, terminalId, title: "Terminal" })
      const status = t.exitStatus ?? (await new Promise((resolve) => t.waiters.push(resolve)))
      terminals.delete(t.id)
      return status
    },
  }

  /* -------------------------------- routing ------------------------------- */

  async function answer(send, msg, table) {
    try {
      const result = await table[msg.method](msg.params ?? {})
      send({ jsonrpc: "2.0", id: msg.id, result: result ?? null })
    } catch (err) {
      send({ jsonrpc: "2.0", id: msg.id, error: { code: err.code ?? -32603, message: err.message, data: err.data } })
    }
  }

  async function fromAgent(line) {
    let msg
    try {
      msg = JSON.parse(line)
    } catch {
      notify("_bridge/agent_stderr", { data: `non-JSON output: ${line}\n` })
      return
    }
    log("agent →", msg.method ?? `response ${msg.id}`)
    if (msg.method && msg.id != null && clientMethods[msg.method]) return answer(toAgent, msg, clientMethods)
    toBrowser(msg)
  }

  ws.on("message", (data) => {
    for (const line of data.toString("utf8").split("\n")) {
      if (!line.trim()) continue
      let msg
      try {
        msg = JSON.parse(line)
      } catch {
        continue
      }
      log("ui →", msg.method ?? `response ${msg.id}`)
      if (msg.method?.startsWith("_bridge/")) {
        if (bridgeMethods[msg.method]) void answer(toBrowser, msg, bridgeMethods)
        else if (msg.id != null) toBrowser({ jsonrpc: "2.0", id: msg.id, error: { code: -32601, message: `Unknown bridge method ${msg.method}` } })
        continue
      }
      if (!toAgent(msg) && msg.id != null && msg.method)
        toBrowser({ jsonrpc: "2.0", id: msg.id, error: { code: -32000, message: "No agent running: send _bridge/spawn first" } })
    }
  })

  ws.on("close", () => {
    agent?.kill()
    for (const t of terminals.values()) if (!t.exitStatus) t.child.kill("SIGTERM")
  })
}

/* --------------------------------- server --------------------------------- */

function tokenOk(given) {
  const a = Buffer.from(String(given ?? ""))
  const b = Buffer.from(TOKEN)
  return a.length === b.length && timingSafeEqual(a, b)
}

const server = createServer((req, res) => {
  res.writeHead(200, { "content-type": "application/json", "access-control-allow-origin": "*" })
  res.end(JSON.stringify({ name: "acp-bridge", root: ROOT, websocket: `ws://${HOST}:${PORT}/?token=…` }))
})

const wss = new WebSocketServer({ noServer: true })
server.on("upgrade", (req, socket, head) => {
  const url = new URL(req.url ?? "/", "http://localhost")
  if (!tokenOk(url.searchParams.get("token"))) {
    socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n")
    socket.destroy()
    return
  }
  wss.handleUpgrade(req, socket, head, (ws) => handleConnection(ws))
})

server.listen(PORT, HOST, () => {
  console.log(`ACP bridge ready
  workspace  ${ROOT}
  address    ws://${HOST}:${PORT}
  token      ${TOKEN}
Paste the address and token into Settings → Agents in the Agent Workspace.`)
})

"use client";

import * as React from "react"

import { cn } from "@/lib/utils"
import { CoverArt } from "@/registry/web/ui/cover-art"
import { GeneratedAvatarImage } from "@/registry/web/ui/generated-avatar"

/**
 * Stand-in artwork drawn from a seed: a still mesh of the seed's palette, with a face on top for
 * portrait styles. No network and no WebGL, so a gallery of them costs nothing; swap in real
 * image URLs (`<img>` with `media-outline`) when you have them.
 */
export function SeededArt({ seed, portrait = false, className }: { seed: string; portrait?: boolean; className?: string }) {
  return (
    <div aria-hidden className={cn("absolute inset-0 overflow-hidden", className)}>
      <CoverArt seed={seed} renderer="css" aria-hidden className="absolute inset-0" />
      {portrait && (
        <div className="absolute inset-x-0 bottom-0 flex justify-center">
          <div className="aspect-square w-4/5">
            <GeneratedAvatarImage seed={seed} background="none" />
          </div>
        </div>
      )}
    </div>
  )
}

/** A gallery tile: the art, its name on a glass label, and the whole tile as one button. */
export function ArtTile({
  label,
  seed,
  portrait,
  height,
  onClick,
  children,
}: {
  label: string
  seed: string
  portrait?: boolean
  height: number
  onClick?: () => void
  children?: React.ReactNode
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{ height }}
      className="group/tile relative mb-3 block w-full cursor-pointer break-inside-avoid overflow-hidden rounded-xl text-start shadow-raised outline-none transition-shadow duration-150 hover:shadow-raised-hover focus-visible:ring-2 focus-visible:ring-ring"
    >
      <SeededArt seed={seed} portrait={portrait} className="transition-transform duration-300 ease-out motion-safe:group-hover/tile:scale-105" />
      <span className="absolute inset-x-2 bottom-2 flex">
        <span className="min-w-0 truncate rounded-control bg-card/80 px-2 py-1 text-ui font-medium text-foreground shadow-raised backdrop-blur-xl">{label}</span>
      </span>
      {children}
    </button>
  )
}

"use client";

import * as React from "react"

import { ImageIcon, PlusIcon, SidebarIcon, SparklesIcon, StarIcon } from "@/components/icons"
import { AgentComposer } from "@/registry/web/blocks/agent-composer/agent-composer"
import { ImageGeneration, type ImageGenerationStatus } from "@/registry/web/ui/image-generation"
import { ComposerPicker } from "@/registry/web/ui/model-picker"
import { PageHeaderTitle } from "@/registry/web/ui/page-header"
import { ScrollArea } from "@/registry/web/ui/scroll-area"
import { SidebarNav, SidebarNavContent, SidebarNavLink, SidebarNavList, SidebarNavSection } from "@/registry/web/ui/sidebar-nav"

import { ArtTile, SeededArt } from "./art-tile"
import { IconAction, SectionPanel, SectionPrimary, SectionSwitcher } from "./section-panel"
import { IMAGE_STYLES } from "./workspace-data"

type Collection = "popular" | "templates" | "yours"
type Generation = { id: string; prompt: string; status: ImageGenerationStatus; aspect: string }

const ASPECTS = [
  { value: "1 / 1", label: "Square" },
  { value: "3 / 4", label: "Portrait" },
  { value: "4 / 3", label: "Landscape" },
]

const TITLES: Record<Collection, string> = { popular: "Popular", templates: "Templates", yours: "Your images" }
const COLLECTIONS: { id: Collection; icon: React.ReactNode }[] = [
  { id: "popular", icon: <StarIcon /> },
  { id: "templates", icon: <SparklesIcon /> },
  { id: "yours", icon: <ImageIcon /> },
]

export function useImages() {
  const [collection, setCollection] = React.useState<Collection>("popular")
  const [generations, setGenerations] = React.useState<Generation[]>([])
  const [draft, setDraft] = React.useState("")
  const [aspect, setAspect] = React.useState(ASPECTS[0].value)
  const timers = React.useRef<number[]>([])
  React.useEffect(() => () => timers.current.forEach((t) => window.clearTimeout(t)), [])

  const generate = (prompt: string) => {
    const id = `img-${Date.now().toString(36)}`
    setGenerations((g) => [{ id, prompt, status: "queued", aspect }, ...g])
    setCollection("yours")
    const step = (status: ImageGenerationStatus, ms: number) =>
      timers.current.push(window.setTimeout(() => setGenerations((g) => g.map((x) => (x.id === id ? { ...x, status } : x))), ms))
    step("generating", 700)
    step("refining", 2600)
    step("complete", 4200)
  }
  return { collection, setCollection, generations, generate, draft, setDraft, aspect, setAspect }
}

export type ImagesState = ReturnType<typeof useImages>

export function ImagesSidebar({
  state,
  onHide,
  onNew,
  onNavigate,
}: {
  state: ImagesState
  onHide?: () => void
  onNew: () => void
  onNavigate?: () => void
}) {
  const go = (c: Collection) => {
    state.setCollection(c)
    onNavigate?.()
  }
  return (
    <SectionPanel
      title="Images"
      actions={
        onHide && (
          <IconAction label="Hide sidebar" shortcut="⌘B" onClick={onHide}>
            <SidebarIcon />
          </IconAction>
        )
      }
      primary={<SectionPrimary icon={<PlusIcon />} label="New image" onClick={onNew} />}
    >
      <SidebarNav indicator="fill">
        <SidebarNavContent aria-label="Image collections">
          <SidebarNavList>
            <SidebarNavLink render={<button type="button" />} className="w-full text-start" icon={<StarIcon />} active={state.collection === "popular"} onClick={() => go("popular")}>
              Popular
            </SidebarNavLink>
            <SidebarNavLink render={<button type="button" />} className="w-full text-start" icon={<SparklesIcon />} active={state.collection === "templates"} onClick={() => go("templates")}>
              Templates
            </SidebarNavLink>
            <SidebarNavLink
              render={<button type="button" />}
              className="w-full text-start"
              icon={<ImageIcon />}
              active={state.collection === "yours"}
              onClick={() => go("yours")}
              badge={state.generations.length > 0 && <span className="text-ui-xs text-muted-foreground tabular-nums">{state.generations.length}</span>}
            >
              Your images
            </SidebarNavLink>
          </SidebarNavList>
          {state.generations.length > 0 && (
            <SidebarNavSection level="label" label="Recent">
              <SidebarNavList>
                {state.generations.slice(0, 8).map((g) => (
                  <SidebarNavLink key={g.id} render={<button type="button" />} className="w-full text-start" onClick={() => go("yours")}>
                    {g.prompt}
                  </SidebarNavLink>
                ))}
              </SidebarNavList>
            </SidebarNavSection>
          )}
        </SidebarNavContent>
      </SidebarNav>
    </SectionPanel>
  )
}

/**
 * A gallery of styles with the composer floating over it. Picking a style starts the prompt
 * instead of generating straight away; a new image lands in Your images and refines in place.
 */
export function ImagesMain({
  state,
  leading,
  composerRef,
}: {
  state: ImagesState
  leading?: React.ReactNode
  composerRef?: React.Ref<HTMLTextAreaElement>
}) {
  const inner = React.useRef<HTMLTextAreaElement>(null)
  React.useImperativeHandle(composerRef, () => inner.current as HTMLTextAreaElement)
  const styles = IMAGE_STYLES.filter((s) => s.collection === state.collection)

  return (
    <div className="relative flex h-full min-w-0 flex-col">
      <ScrollArea className="min-h-0 flex-1">
        <div className="mx-auto flex w-full max-w-6xl flex-col gap-5 px-5 pt-6 pb-40 md:px-8 md:pt-8">
          <div className="flex items-center gap-2">
            {leading}
            <PageHeaderTitle>{TITLES[state.collection]}</PageHeaderTitle>
            {leading && (
              <SectionSwitcher
                label="Switch collection"
                value={state.collection}
                onValueChange={(v) => state.setCollection(v as Collection)}
                groups={[{ options: COLLECTIONS.map((c) => ({ value: c.id, label: TITLES[c.id], icon: c.icon })) }]}
              />
            )}
          </div>
          {state.collection === "yours" ? (
            state.generations.length === 0 ? (
              <p className="text-ui text-muted-foreground">Describe an image below, or start from a style in Popular.</p>
            ) : (
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">
                {state.generations.map((g) => (
                  <ImageGeneration key={g.id} status={g.status} prompt={g.prompt} aspectRatio={g.aspect} alt={g.prompt} className="max-w-none">
                    <div className="relative size-full">
                      <SeededArt seed={g.prompt} portrait={/portrait|face|person|avatar/i.test(g.prompt)} />
                    </div>
                  </ImageGeneration>
                ))}
              </div>
            )
          ) : (
            <div className="columns-2 gap-3 md:columns-3 xl:columns-4">
              {styles.map((s) => (
                <ArtTile
                  key={s.id}
                  label={s.label}
                  seed={s.seed}
                  portrait={s.portrait}
                  height={s.rows * 8}
                  onClick={() => {
                    state.setDraft(`${s.label} style, `)
                    requestAnimationFrame(() => inner.current?.focus())
                  }}
                />
              ))}
            </div>
          )}
        </div>
      </ScrollArea>
      <div className="pointer-events-none absolute inset-x-0 bottom-0 px-4 pb-4">
        <div className="pointer-events-auto mx-auto w-full max-w-2xl">
          <AgentComposer
            ref={inner}
            value={state.draft}
            onValueChange={state.setDraft}
            placeholder="Describe an image"
            onSubmit={(t) => {
              state.setDraft("")
              state.generate(t)
            }}
            onVoice={() => inner.current?.focus()}
            toolbarEnd={<ComposerPicker label="Aspect ratio" options={ASPECTS} value={state.aspect} onValueChange={state.setAspect} align="end" />}
          />
        </div>
      </div>
    </div>
  )
}

