export function useLibrary() {
  const [shelf, setShelf] = React.useState<Shelf>("recommended")
  const [layout, setLayout] = React.useState<"grid" | "list">("grid")
  const [query, setQuery] = React.useState("")
  const [favourites, setFavourites] = React.useState<Record<string, boolean>>(() =>
    Object.fromEntries(LIBRARY_ITEMS.map((i) => [i.id, !!i.favourite]))
  )
  const toggleFavourite = (id: string) => setFavourites((f) => ({ ...f, [id]: !f[id] }))
  return { shelf, setShelf, layout, setLayout, query, setQuery, favourites, toggleFavourite }
}

export type LibraryState = ReturnType<typeof useLibrary>

function shelfTitle(shelf: Shelf) {
  return shelf.startsWith("project:") ? shelf.slice(8) : SHELVES.find((s) => s.id === shelf)?.label
}

export function LibrarySidebar({ state, onHide, onNew, onNavigate }: { state: LibraryState; onHide?: () => void; onNew: () => void; onNavigate?: () => void }) {
  const go = (s: Shelf) => {
    state.setShelf(s)
    onNavigate?.()
  }
  return (
    <SectionPanel
      title="Library"
      actions={
        onHide && (
          <IconAction label="Hide sidebar" shortcut="⌘B" onClick={onHide}>
            <SidebarIcon />
          </IconAction>
        )
      }
      primary={<SectionPrimary icon={<EditIcon />} label="New chat" shortcut="⌘N" onClick={onNew} />}
    >
      <SidebarNav indicator="fill">
        <SidebarNavContent aria-label="Library">
          <SidebarNavList>
            {SHELVES.map((s) => (
              <SidebarNavLink key={s.id} render={<button type="button" />} className="w-full text-start" icon={s.icon} active={state.shelf === s.id} onClick={() => go(s.id)}>
                {s.label}
              </SidebarNavLink>
            ))}
          </SidebarNavList>
          <SidebarNavSection level="label" label="Folders">
            <SidebarNavList>
              {PROJECTS.map((p) => {
                const count = LIBRARY_ITEMS.filter((i) => i.project === p.id).length
                return (
                  <SidebarNavLink
                    key={p.id}
                    render={<button type="button" />}
                    className="w-full text-start"
                    icon={<FolderIcon />}
                    active={state.shelf === `project:${p.id}`}
                    onClick={() => go(`project:${p.id}`)}
                    badge={<span className="text-ui-xs text-muted-foreground tabular-nums">{count}</span>}
                  >
                    {p.name}
                  </SidebarNavLink>
                )
              })}
            </SidebarNavList>
          </SidebarNavSection>
        </SidebarNavContent>
      </SidebarNav>
    </SectionPanel>
  )
}

function FavouriteButton({ on, onClick, title }: { on: boolean; onClick: () => void; title: string }) {
  return (
    <IconAction label={on ? `Remove ${title} from favourites` : `Add ${title} to favourites`} size="icon-xs" pressed={on} onClick={onClick}>
      <StarIcon className={cn(on && "text-warning-text")} />
    </IconAction>
  )
}

function LibraryCard({ item, favourite, onFavourite }: { item: LibraryItem; favourite: boolean; onFavourite: () => void }) {
  const meta = (
    <CardFooter className="justify-between gap-2">
      <span className="truncate text-ui-sm text-muted-foreground">
        {item.project} · {item.updated}
      </span>
      <FavouriteButton on={favourite} onClick={onFavourite} title={item.title} />
    </CardFooter>
  )
  if (item.kind === "image")
    return (
      <Card size="sm" className="mb-3 break-inside-avoid pt-0">
        <div className="relative" style={{ height: item.rows * 8 - 64 }}>
          <SeededArt seed={item.seed} />
        </div>
        <CardHeader>
          <CardTitle className="truncate">{item.title}</CardTitle>
        </CardHeader>
        {meta}
      </Card>
    )
  return (
    <Card size="sm" className="mb-3 break-inside-avoid">
      <CardHeader className="flex-row items-center gap-2">
        <span className="flex text-muted-foreground [&_svg]:size-4">{KIND_ICON[item.kind]}</span>
        <CardTitle className="min-w-0 truncate">{item.title}</CardTitle>
      </CardHeader>
      <CardContent>
        {item.kind === "code" ? (
          <pre className="overflow-hidden rounded-md bg-muted p-2 font-mono text-ui-xs whitespace-pre-wrap text-muted-foreground">{item.excerpt}</pre>
        ) : (
          <p className="text-ui text-pretty text-muted-foreground">{item.excerpt}</p>
        )}
      </CardContent>
      {meta}
    </Card>
  )
}

/** Masonry while it loads, so the page keeps its shape when the cards arrive. */
function LibrarySkeleton() {
  return (
    <div role="status" aria-label="Loading library" className="columns-1 gap-3 sm:columns-2 lg:columns-3 xl:columns-4">
      {[26, 34, 22, 30, 24, 28, 30, 22].map((rows, i) => (
        <Skeleton key={i} shape="card" className="mb-3 break-inside-avoid" style={{ height: rows * 8 }} />
      ))}
    </div>
  )
}

export function LibraryMain({ state, leading }: { state: LibraryState; leading?: React.ReactNode }) {
  const [loading, setLoading] = React.useState(true)
  React.useEffect(() => {
    const t = window.setTimeout(() => setLoading(false), 700)
    return () => window.clearTimeout(t)
  }, [])

  const q = state.query.toLowerCase()
  const items = LIBRARY_ITEMS.filter((i) => {
    if (state.shelf === "favourites" && !state.favourites[i.id]) return false
    if (state.shelf === "images" && i.kind !== "image") return false
    if (state.shelf === "recommended" && i.updated.includes("Oct")) return false
    if (state.shelf.startsWith("project:") && i.project !== state.shelf.slice(8)) return false
    return !q || `${i.title} ${i.project} ${i.excerpt ?? ""}`.toLowerCase().includes(q)
  })

  return (
    <ScrollArea className="h-full min-w-0">
      <div className="mx-auto flex w-full max-w-6xl flex-col gap-5 px-5 pt-6 pb-10 md:px-8 md:pt-8">
        <div className="flex flex-wrap items-center gap-x-3 gap-y-3">
          <div className="flex min-w-0 flex-1 items-center gap-2">
            {leading}
            <PageHeaderTitle className="truncate">{shelfTitle(state.shelf)}</PageHeaderTitle>
            {leading && (
              <SectionSwitcher
                label="Switch shelf"
                value={state.shelf}
                onValueChange={(v) => state.setShelf(v as Shelf)}
                groups={[
                  { options: SHELVES.map((s) => ({ value: s.id, label: s.label, icon: s.icon })) },
                  { label: "Folders", options: PROJECTS.map((p) => ({ value: `project:${p.id}`, label: p.name, icon: <FolderIcon /> })) },
                ]}
              />
            )}
          </div>
          <InputGroup className="w-full sm:w-64">
            <InputGroupAddon>
              <SearchIcon />
            </InputGroupAddon>
            <InputGroupInput value={state.query} onChange={(e) => state.setQuery(e.target.value)} placeholder="Search the library" aria-label="Search the library" />
          </InputGroup>
          <ToggleGroup
            aria-label="Layout"
            value={[state.layout]}
            onValueChange={(v) => v[0] && state.setLayout(v[0] as "grid" | "list")}
          >
            <ToggleGroupItem value="grid" aria-label="Grid">
              <GridIcon />
            </ToggleGroupItem>
            <ToggleGroupItem value="list" aria-label="List">
              <ListIcon />
            </ToggleGroupItem>
          </ToggleGroup>
        </div>

        {loading ? (
          <LibrarySkeleton />
        ) : items.length === 0 ? (
          <EmptyState variant="outline">
            <EmptyStateTitle>{state.query ? "Nothing matches" : "Nothing here yet"}</EmptyStateTitle>
            <EmptyStateDescription>
              {state.query ? "Try another word, or look in All files." : "Star a file to keep it in Favourites."}
            </EmptyStateDescription>
            {state.query && (
              <Button variant="ghost" size="sm" className="mt-2" onClick={() => state.setQuery("")}>
                Clear search
              </Button>
            )}
          </EmptyState>
        ) : state.layout === "grid" ? (
          <div className="columns-1 gap-3 sm:columns-2 lg:columns-3 xl:columns-4">
            {items.map((i) => (
              <LibraryCard key={i.id} item={i} favourite={!!state.favourites[i.id]} onFavourite={() => state.toggleFavourite(i.id)} />
            ))}
          </div>
        ) : (
          <SimpleTable>
            <SimpleTableHeader>
              <SimpleTableRow>
                <SimpleTableHead>Name</SimpleTableHead>
                <SimpleTableHead>Folder</SimpleTableHead>
                <SimpleTableHead>Updated</SimpleTableHead>
                <SimpleTableHead align="end">
                  <span className="sr-only">Favourite</span>
                </SimpleTableHead>
              </SimpleTableRow>
            </SimpleTableHeader>
            <SimpleTableBody>
              {items.map((i) => (
                <SimpleTableRow key={i.id}>
                  <SimpleTableCell>
                    <span className="flex items-center gap-2">
                      <span className="flex text-muted-foreground [&_svg]:size-4">{KIND_ICON[i.kind]}</span>
                      <span className="truncate font-medium">{i.title}</span>
                    </span>
                  </SimpleTableCell>
                  <SimpleTableCell>{i.project}</SimpleTableCell>
                  <SimpleTableCell>{i.updated}</SimpleTableCell>
                  <SimpleTableCell align="end">
                    <FavouriteButton on={!!state.favourites[i.id]} onClick={() => state.toggleFavourite(i.id)} title={i.title} />
                  </SimpleTableCell>
                </SimpleTableRow>
              ))}
            </SimpleTableBody>
          </SimpleTable>
        )}
      </div>
    </ScrollArea>
  )
}

"use client";

import * as React from "react"

import { CheckIcon, ChevronDownIcon, FolderIcon } from "@/components/icons"
import { AgentComposer } from "@/registry/web/blocks/agent-composer/agent-composer"
import { Button } from "@/registry/web/ui/button"
import { Menu, MenuContent, MenuGroup, MenuItem, MenuLabel, MenuTrigger } from "@/registry/web/ui/menu"
import { ThinkingModelPicker, type EffortLevel, type ModelOption } from "@/registry/web/ui/model-picker"

import { ProviderIcon } from "./provider-icon"

const STARTERS = ["Explain this project", "Fix a failing test", "Write tests for my last change"]

export type ModelChoice = { models: ModelOption[]; levels: EffortLevel[]; model: string; effort: string }

/**
 * A chat that hasn't started. The question sits in the open space; the composer sits exactly where
 * a thread's composer does, so sending doesn't move it. Starters fill the composer instead of
 * sending, so they can be edited first.
 */
export function NewChat({
  provider,
  ready,
  projects,
  project,
  onProjectChange,
  choice,
  onChoiceChange,
  onSubmit,
  composerRef,
}: {
  provider?: string
  ready: boolean
  projects: string[]
  project: string
  onProjectChange: (project: string) => void
  choice: ModelChoice | null
  onChoiceChange: (choice: ModelChoice) => void
  onSubmit: (text: string) => void
  composerRef?: React.Ref<HTMLTextAreaElement>
}) {
  const [text, setText] = React.useState("")
  const inner = React.useRef<HTMLTextAreaElement>(null)
  React.useImperativeHandle(composerRef, () => inner.current as HTMLTextAreaElement)

  return (
    <div className="flex h-full min-w-0 flex-col">
      <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-4 overflow-y-auto px-5 py-10 text-center">
        <ProviderIcon provider={provider} className="size-7" />
        <h2 className="font-heading text-2xl font-semibold tracking-tight text-balance">What should we build?</h2>
      </div>
      <div className="shrink-0 px-4 pb-3">
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-2">
          <div className="flex flex-wrap gap-1.5" aria-label="Starters" role="group">
            {STARTERS.map((s) => (
              <Button
                key={s}
                variant="outline"
                size="sm"
                className="text-muted-foreground"
                onClick={() => {
                  setText(s)
                  requestAnimationFrame(() => inner.current?.focus())
                }}
              >
                {s}
              </Button>
            ))}
          </div>
          <AgentComposer
            ref={inner}
            value={text}
            onValueChange={setText}
            disabled={!ready}
            placeholder={ready ? "Ask anything, @ to add files" : "Connecting to the agent…"}
            onSubmit={(t) => {
              setText("")
              onSubmit(t)
            }}
            onVoice={() => inner.current?.focus()}
            toolbarStart={
              <Menu>
                <MenuTrigger render={<Button variant="ghost" size="xs" className="min-w-0 text-muted-foreground" aria-label={`Project, ${project}`} />}>
                  <FolderIcon data-icon="inline-start" />
                  <span className="truncate font-normal">{project}</span>
                  <ChevronDownIcon data-icon="inline-end" className="size-3 opacity-64" />
                </MenuTrigger>
                <MenuContent className="w-52" side="top" align="start">
                  <MenuGroup>
                    <MenuLabel>Project</MenuLabel>
                    {projects.map((p) => (
                      <MenuItem key={p} onClick={() => onProjectChange(p)}>
                        <FolderIcon />
                        <span className="min-w-0 flex-1 truncate">{p}</span>
                        {p === project && <CheckIcon className="!text-foreground" />}
                      </MenuItem>
                    ))}
                  </MenuGroup>
                </MenuContent>
              </Menu>
            }
            toolbarEnd={
              choice ? (
                <ThinkingModelPicker
                  models={choice.models}
                  value={choice.model}
                  onValueChange={(model) => onChoiceChange({ ...choice, model })}
                  levels={choice.levels}
                  effort={choice.effort}
                  onEffortChange={(effort) => onChoiceChange({ ...choice, effort })}
                  align="end"
                />
              ) : null
            }
          />
        </div>
      </div>
    </div>
  )
}

"use client";

import * as React from "react"

import { BoltIcon, CheckIcon, PlugIcon, PlusIcon, SearchIcon, SidebarIcon } from "@/components/icons"
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator } from "@/registry/web/ui/breadcrumb"
import { Button } from "@/registry/web/ui/button"
import { EmptyState, EmptyStateDescription } from "@/registry/web/ui/empty-state"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/web/ui/input-group"
import { PageHeaderTitle } from "@/registry/web/ui/page-header"
import { ScrollArea } from "@/registry/web/ui/scroll-area"
import {
  SettingsGroup,
  SettingsRow,
  SettingsRowDescription,
  SettingsRowText,
  SettingsRowTitle,
  SettingsSection,
  SettingsSectionHeader,
  SettingsSectionTitle,
} from "@/registry/web/ui/settings-section"
import { SidebarNav, SidebarNavContent, SidebarNavLink, SidebarNavList, SidebarNavSection } from "@/registry/web/ui/sidebar-nav"
import { Switch } from "@/registry/web/ui/switch"
import { Tabs, TabsList, TabsTab } from "@/registry/web/ui/tabs"

import { IconAction, PageBody, SectionPanel, SectionPrimary, SectionSwitcher } from "./section-panel"
import { ItemChip, ItemGlyph } from "./view-icons"
import { PLUGINS, SKILLS, type Plugin } from "./workspace-data"

type Page = { kind: "browse" } | { kind: "skills" } | { kind: "plugin"; id: string }

export function usePlugins() {
  const [page, setPage] = React.useState<Page>({ kind: "browse" })
  const [installed, setInstalled] = React.useState<Record<string, boolean>>(() => Object.fromEntries(PLUGINS.map((p) => [p.id, !!p.installed])))
  const [skills, setSkills] = React.useState<Record<string, boolean>>({ review: true, release: true })
  const toggle = (id: string) => setInstalled((s) => ({ ...s, [id]: !s[id] }))
  return { page, setPage, installed, toggle, skills, setSkills }
}

export type PluginsState = ReturnType<typeof usePlugins>

export function PluginsSidebar({ state, onHide, onNavigate }: { state: PluginsState; onHide?: () => void; onNavigate?: () => void }) {
  const go = (p: Page) => {
    state.setPage(p)
    onNavigate?.()
  }
  const installed = PLUGINS.filter((p) => state.installed[p.id])
  return (
    <SectionPanel
      title="Plugins"
      actions={
        onHide && (
          <IconAction label="Hide sidebar" shortcut="⌘B" onClick={onHide}>
            <SidebarIcon />
          </IconAction>
        )
      }
      primary={<SectionPrimary icon={<PlusIcon />} label="Add plugin" onClick={() => go({ kind: "browse" })} />}
    >
      <SidebarNav indicator="fill">
        <SidebarNavContent aria-label="Plugins">
          <SidebarNavList>
            <SidebarNavLink render={<button type="button" />} className="w-full text-start" icon={<PlugIcon />} active={state.page.kind === "browse"} onClick={() => go({ kind: "browse" })}>
              Browse
            </SidebarNavLink>
            <SidebarNavLink render={<button type="button" />} className="w-full text-start" icon={<BoltIcon />} active={state.page.kind === "skills"} onClick={() => go({ kind: "skills" })}>
              Skills
            </SidebarNavLink>
          </SidebarNavList>
          <SidebarNavSection level="label" label="Installed" count={installed.length}>
            <SidebarNavList>
              {installed.map((p) => (
                <SidebarNavLink
                  key={p.id}
                  render={<button type="button" />}
                  className="w-full text-start"
                  icon={<ItemGlyph icon={p.icon} />}
                  active={state.page.kind === "plugin" && state.page.id === p.id}
                  onClick={() => go({ kind: "plugin", id: p.id })}
                >
                  {p.name}
                </SidebarNavLink>
              ))}
            </SidebarNavList>
          </SidebarNavSection>
        </SidebarNavContent>
      </SidebarNav>
    </SectionPanel>
  )
}

function PluginRow({ plugin, installed, onOpen, onToggle }: { plugin: Plugin; installed: boolean; onOpen: () => void; onToggle: () => void }) {
  return (
    <li className="flex items-center gap-1">
      <button
        type="button"
        onClick={onOpen}
        className="flex min-w-0 flex-1 cursor-pointer items-center gap-3 rounded-inner p-2 text-start text-ui outline-none transition-colors duration-150 hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring"
      >
        <ItemChip icon={plugin.icon} tone={plugin.tone} size="lg" />
        <span className="flex min-w-0 flex-col">
          <span className="truncate font-medium">{plugin.name}</span>
          <span className="truncate text-muted-foreground">{plugin.description}</span>
        </span>
      </button>
      <IconAction label={installed ? `${plugin.name} is installed` : `Install ${plugin.name}`} pressed={installed} onClick={onToggle}>
        {installed ? <CheckIcon /> : <PlusIcon />}
      </IconAction>
    </li>
  )
}

function Browse({ state, leading, switcher }: { state: PluginsState; leading?: React.ReactNode; switcher?: React.ReactNode }) {
  const [scope, setScope] = React.useState<"public" | "personal">("public")
  const [query, setQuery] = React.useState("")
  const q = query.toLowerCase()
  const list = PLUGINS.filter((p) => p.scope === scope && (!q || `${p.name} ${p.description}`.toLowerCase().includes(q)))
  const sections = [
    { id: "popular", label: "Popular" },
    { id: "new", label: "New" },
  ].map((s) => ({ ...s, items: list.filter((p) => p.section === s.id) }))

  return (
    <PageBody wide>
      <div className="flex flex-wrap items-center gap-3">
        <div className="flex min-w-0 flex-1 items-center gap-2">
          {leading}
          <PageHeaderTitle>Plugins</PageHeaderTitle>
          {switcher}
        </div>
        <InputGroup className="w-full sm:w-64">
          <InputGroupAddon>
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search plugins" aria-label="Search plugins" />
        </InputGroup>
      </div>
      <Tabs value={scope} onValueChange={(v) => setScope(v as "public" | "personal")}>
        <TabsList variant="ghost" aria-label="Source">
          <TabsTab value="public">Public</TabsTab>
          <TabsTab value="personal">Your team</TabsTab>
        </TabsList>
      </Tabs>
      {list.length === 0 ? (
        <EmptyState variant="outline" size="sm">
          <EmptyStateDescription>No plugins match.</EmptyStateDescription>
        </EmptyState>
      ) : (
        sections
          .filter((s) => s.items.length)
          .map((s) => (
            <section key={s.id} className="flex flex-col gap-2" aria-labelledby={`plugins-${s.id}`}>
              <h2 id={`plugins-${s.id}`} className="text-sm font-semibold text-balance">
                {s.label}
              </h2>
              <ul className="-mx-2 grid gap-x-6 gap-y-1 md:grid-cols-2">
                {s.items.map((p) => (
                  <PluginRow
                    key={p.id}
                    plugin={p}
                    installed={!!state.installed[p.id]}
                    onOpen={() => state.setPage({ kind: "plugin", id: p.id })}
                    onToggle={() => state.toggle(p.id)}
                  />
                ))}
              </ul>
            </section>
          ))
      )}
    </PageBody>
  )
}

function Detail({ plugin, state, leading, switcher }: { plugin: Plugin; state: PluginsState; leading?: React.ReactNode; switcher?: React.ReactNode }) {
  const installed = !!state.installed[plugin.id]
  return (
    <PageBody>
      <div className="flex items-center gap-2">
        {leading}
        <Breadcrumb>
          <BreadcrumbList>
            <BreadcrumbItem>
              <BreadcrumbLink render={<button type="button" />} onClick={() => state.setPage({ kind: "browse" })}>
                Plugins
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator />
            <BreadcrumbItem>
              <BreadcrumbPage>{plugin.name}</BreadcrumbPage>
            </BreadcrumbItem>
          </BreadcrumbList>
        </Breadcrumb>
        {switcher}
      </div>
      <div className="flex flex-wrap items-center gap-4">
        <ItemChip icon={plugin.icon} tone={plugin.tone} size="xl" />
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <PageHeaderTitle>{plugin.name}</PageHeaderTitle>
          <p className="text-ui text-muted-foreground">{plugin.description}</p>
        </div>
        <Button variant={installed ? "outline" : "default"} onClick={() => state.toggle(plugin.id)}>
          {installed ? "Remove" : "Install"}
        </Button>
      </div>
      <p className="text-sm text-pretty">{plugin.about}</p>
      <SettingsSection>
        <SettingsSectionHeader>
          <SettingsSectionTitle>Tools</SettingsSectionTitle>
        </SettingsSectionHeader>
        <SettingsGroup>
          {plugin.tools.map((t) => (
            <SettingsRow key={t.name}>
              <SettingsRowText>
                <SettingsRowTitle>
                  <code className="font-mono">{t.name}</code>
                </SettingsRowTitle>
                <SettingsRowDescription>{t.description}</SettingsRowDescription>
              </SettingsRowText>
            </SettingsRow>
          ))}
        </SettingsGroup>
      </SettingsSection>
      <SettingsSection>
        <SettingsSectionHeader>
          <SettingsSectionTitle>Details</SettingsSectionTitle>
        </SettingsSectionHeader>
        <SettingsGroup>
          {[
            ["Access", plugin.capabilities],
            ["Category", plugin.category],
            ["Version", plugin.version],
          ].map(([k, v]) => (
            <SettingsRow key={k} size="sm">
              <span className="text-muted-foreground">{k}</span>
              <span>{v}</span>
            </SettingsRow>
          ))}
        </SettingsGroup>
      </SettingsSection>
    </PageBody>
  )
}

function Skills({ state, leading, switcher }: { state: PluginsState; leading?: React.ReactNode; switcher?: React.ReactNode }) {
  return (
    <PageBody>
      <div className="flex items-center gap-2">
        {leading}
        <PageHeaderTitle>Skills</PageHeaderTitle>
        {switcher}
      </div>
      <SettingsGroup>
        {SKILLS.map((s) => (
          <SettingsRow key={s.id} render={<label />}>
            <SettingsRowText>
              <SettingsRowTitle>{s.name}</SettingsRowTitle>
              <SettingsRowDescription>{s.description}</SettingsRowDescription>
            </SettingsRowText>
            <Switch checked={!!state.skills[s.id]} onCheckedChange={(on) => state.setSkills((x) => ({ ...x, [s.id]: on }))} />
          </SettingsRow>
        ))}
      </SettingsGroup>
    </PageBody>
  )
}

export function PluginsMain({ state, leading }: { state: PluginsState; leading?: React.ReactNode }) {
  const plugin = state.page.kind === "plugin" ? PLUGINS.find((p) => p.id === (state.page as { id: string }).id) : undefined
  const value = state.page.kind === "plugin" ? `plugin:${state.page.id}` : state.page.kind
  const switcher = leading && (
    <SectionSwitcher
      label="Switch page"
      value={value}
      onValueChange={(v) => state.setPage(v.startsWith("plugin:") ? { kind: "plugin", id: v.slice(7) } : { kind: v as "browse" | "skills" })}
      groups={[
        {
          options: [
            { value: "browse", label: "Browse", icon: <PlugIcon /> },
            { value: "skills", label: "Skills", icon: <BoltIcon /> },
          ],
        },
        { label: "Installed", options: PLUGINS.filter((p) => state.installed[p.id]).map((p) => ({ value: `plugin:${p.id}`, label: p.name, icon: <ItemGlyph icon={p.icon} /> })) },
      ]}
    />
  )
  return (
    <ScrollArea className="h-full min-w-0">
      {plugin ? (
        <Detail plugin={plugin} state={state} leading={leading} switcher={switcher} />
      ) : state.page.kind === "skills" ? (
        <Skills state={state} leading={leading} switcher={switcher} />
      ) : (
        <Browse state={state} leading={leading} switcher={switcher} />
      )}
    </ScrollArea>
  )
}

