export function TasksMain({ state, leading }: { state: ScheduledTasksState; leading?: React.ReactNode }) {
  const task = state.tasks.find((t) => t.id === state.selected)
  const switcher = leading && state.tasks.length > 0 && (
    <SectionSwitcher
      label="Switch task"
      value={state.selected ?? "new"}
      onValueChange={(v) => state.setSelected(v === "new" ? null : v)}
      groups={[
        { options: [{ value: "new", label: "New task", icon: <PlusIcon /> }] },
        { label: "Tasks", options: state.tasks.map((t) => ({ value: t.id, label: t.title, icon: <ItemGlyph icon={t.icon} /> })) },
      ]}
    />
  )
  return (
    <div className="flex h-full min-w-0 flex-col">
      {leading && !task && (
        <div className="flex h-10 shrink-0 items-center gap-1 px-2">
          {leading}
          {switcher && <span className="ms-1 text-ui font-medium">New task</span>}
          {switcher}
        </div>
      )}
      <ScrollArea className="min-h-0 flex-1">
        {task ? (
          <TaskDetail task={task} state={state} leading={leading} switcher={switcher} />
        ) : (
          <TaskTemplates onPick={state.create} onBlank={() => state.create(null)} />
        )}
      </ScrollArea>
    </div>
  )
}

function TaskDetail({
  task,
  state,
  leading,
  switcher,
}: {
  task: ScheduledTask
  state: ScheduledTasksState
  leading?: React.ReactNode
  switcher?: React.ReactNode
}) {
  const runNow = () =>
    state.update(task.id, {
      runs: [{ at: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), ok: task.prompt.trim().length > 0 }, ...task.runs].slice(0, 6),
    })
  return (
    <PageBody>
      <div className="flex items-center gap-3">
        {leading}
        <ItemChip icon={task.icon} tone={task.tone} size="lg" />
        <div className="flex min-w-0 flex-1 items-center gap-2">
          <PageHeaderTitle className="truncate">{task.title}</PageHeaderTitle>
          {switcher}
        </div>
        <Button variant="outline" size="sm" onClick={runNow}>
          <PlayIcon data-icon="inline-start" />
          Run now
        </Button>
        <Menu>
          <MenuTrigger render={<Button variant="ghost" size="icon-sm" aria-label="More actions" className="text-muted-foreground" />}>
            <MoreHorizontalIcon />
          </MenuTrigger>
          <MenuContent align="end" className="w-44">
            <MenuItem onClick={() => state.update(task.id, { enabled: !task.enabled })}>{task.enabled ? "Pause" : "Resume"}</MenuItem>
            <MenuSeparator />
            <MenuItem variant="destructive" onClick={() => state.remove(task.id)}>
              <TrashIcon />
              Delete task
            </MenuItem>
          </MenuContent>
        </Menu>
      </div>

      <SettingsGroup>
        <SettingsRow render={<label />}>
          <SettingsRowText>
            <SettingsRowTitle>Active</SettingsRowTitle>
            <SettingsRowDescription>{task.enabled ? `Next run ${task.schedule.toLowerCase()}.` : "Paused until you turn it back on."}</SettingsRowDescription>
          </SettingsRowText>
          <Switch checked={task.enabled} onCheckedChange={(enabled) => state.update(task.id, { enabled })} />
        </SettingsRow>
        <SettingsRow>
          <SettingsRowText>
            <SettingsRowTitle>Schedule</SettingsRowTitle>
          </SettingsRowText>
          <Select value={task.schedule} onValueChange={(v) => state.update(task.id, { schedule: v as string })}>
            <SelectTrigger aria-label="Schedule" className="w-48">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(SCHEDULE_OPTIONS.includes(task.schedule) ? SCHEDULE_OPTIONS : [task.schedule, ...SCHEDULE_OPTIONS]).map((o) => (
                <SelectItem key={o} value={o}>
                  {o}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </SettingsRow>
        <SettingsRow>
          <SettingsRowText>
            <SettingsRowTitle>Project</SettingsRowTitle>
          </SettingsRowText>
          <Select defaultValue={PROJECTS[0].id}>
            <SelectTrigger aria-label="Project" className="w-48">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {PROJECTS.map((p) => (
                <SelectItem key={p.id} value={p.id}>
                  {p.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </SettingsRow>
      </SettingsGroup>

      <SettingsSection>
        <SettingsSectionHeader>
          <SettingsSectionTitle>Prompt</SettingsSectionTitle>
        </SettingsSectionHeader>
        <Textarea
          value={task.prompt}
          onChange={(e) => state.update(task.id, { prompt: e.target.value })}
          placeholder="What should the agent do each time?"
          aria-label="Prompt"
          rows={4}
        />
      </SettingsSection>

      <SettingsSection>
        <SettingsSectionHeader>
          <SettingsSectionTitle>Runs</SettingsSectionTitle>
        </SettingsSectionHeader>
        {task.runs.length === 0 ? (
          <EmptyState variant="outline" size="sm">
            <EmptyStateDescription>Runs show up here. Try one now to check the prompt.</EmptyStateDescription>
          </EmptyState>
        ) : (
          <SettingsGroup>
            {task.runs.map((r, i) => (
              <SettingsRow key={i}>
                <span className="flex items-center gap-2">
                  {r.ok ? <CheckCircleIcon className="size-4 text-success-text" /> : <XCircleIcon className="size-4 text-destructive-text" />}
                  <span>{r.ok ? "Finished" : "Failed, the prompt is empty"}</span>
                </span>
                <span className={cn("text-ui-sm text-muted-foreground tabular-nums")}>Today {r.at}</span>
              </SettingsRow>
            ))}
          </SettingsGroup>
        )}
      </SettingsSection>
    </PageBody>
  )
}

"use client";

import * as React from "react"

import {
  CalendarDaysIcon,
  ChartIcon,
  CloudIcon,
  DatabaseIcon,
  GitPullRequestIcon,
  GlobeIcon,
  LockIcon,
  MailIcon,
  ShieldIcon,
  TerminalSquareIcon,
} from "@/components/icons"
import { IconChip } from "@/registry/web/ui/icon-chip"

import type { PluginIcon, TaskIcon, TaskTone } from "./workspace-data"

const GLYPHS: Record<TaskIcon | PluginIcon, React.ComponentType> = {
  chart: ChartIcon,
  mail: MailIcon,
  pr: GitPullRequestIcon,
  terminal: TerminalSquareIcon,
  shield: ShieldIcon,
  calendar: CalendarDaysIcon,
  database: DatabaseIcon,
  cloud: CloudIcon,
  globe: GlobeIcon,
  lock: LockIcon,
}

/** A task or plugin glyph in the house chip, tinted by its tone. */
export function ItemChip({ icon, tone, size = "default" }: { icon: TaskIcon | PluginIcon; tone: TaskTone; size?: "sm" | "default" | "lg" | "xl" }) {
  const Glyph = GLYPHS[icon]
  return (
    <IconChip tone={tone} size={size}>
      <Glyph />
    </IconChip>
  )
}

/** The bare glyph, for nav rows. */
export function ItemGlyph({ icon }: { icon: TaskIcon | PluginIcon }) {
  const Glyph = GLYPHS[icon]
  return <Glyph />
}
